   243	/// Create a fresh proposal package. Success never means installed, issued,
   244	/// admitted, live-qualified, reviewed or accepted.
   245	pub fn prepare(input_path: &Path, output: &Path) -> Result<Value> {
   246	    if !input_path.is_absolute()
   247	        || !output.is_absolute()
   248	        || fs::canonicalize(input_path)? != input_path
   249	        || output.exists()
   250	        || fs::canonicalize(
   251	            output
   252	                .parent()
   253	                .ok_or_else(|| error("output parent absent"))?,
   254	        )? != output.parent().unwrap()
   255	    {
   256	        return Err(error(
   257	            "input must be canonical and output a new canonical child",
   258	        ));
   259	    }
   260	    let file = fs::File::open(input_path)?;
   261	    if !file.metadata()?.is_file() {
   262	        return Err(error("input must be a regular file"));
   263	    }
   264	    let mut bytes = Vec::new();
   265	    file.take(1024 * 1024 + 1).read_to_end(&mut bytes)?;
   266	    if bytes.len() > 1024 * 1024 {
   267	        return Err(error("input exceeds1MiB"));
   268	    }
   269	    let mut input: PreparationInput = serde_json::from_slice(&bytes)?;
   270	    if input.schema_version != 1
   271	        || input.standing != "uninstalled-proposal"
   272	        || input.startup.profile != QUALIFIED_PROFILE
   273	        || input.startup.base.profile != QUALIFIED_PROFILE
   274	        || input.startup.base.evidence_profile != "claude-qualified-v1"
   275	    {
   276	        return Err(error(
   277	            "only explicit qualified uninstalled proposal data is supported; fixture/control standing refused",
   278	        ));
   279	    }
   280	    let provenance_raw = input.provenance.read(1024 * 1024)?;
   281	    let provenance: Value = serde_json::from_slice(&provenance_raw)?;
   282	    let origin = provenance["repository_path"]
   283	        .as_str()
   284	        .ok_or_else(|| error("genuine-origin repository_path absent"))?;
   285	    if Path::new(origin).is_absolute()
   286	        || Path::new(origin)
   287	            .components()
   288	            .any(|part| !matches!(part, std::path::Component::Normal(_)))
   289	        || !input.candidate_paths.iter().any(|path| path == origin)
   290	    {
   291	        return Err(error(
   292	            "genuine-origin path must be an explicit confined candidate path",
   293	        ));
   294	    }
   295	    // Establish complete authority data before checkpoint/index effects. This is
   296	    // syntax/pin validation only; issuance remains with the selected owner.
   297	    for pin in [
   298	        &input.startup.base.claims.source,
   299	        &input.startup.base.claims.configuration,
   300	        &input.startup.base.episode_authority,
   301	    ] {
   302	        let _: Value = serde_json::from_slice(&pin.read(1024 * 1024)?)?;
   303	    }
   304	    if sha256_bytes(&fs::read(input.startup.base.repository.join(origin))?)
   305	        != provenance["candidate_file_sha256"]
   306	        || provenance["actual_source_receipt"]
   307	            .as_str()
   308	            .is_none_or(str::is_empty)
   309	    {
   310	        return Err(error(
   311	            "genuine-origin candidate bytes/receipt provenance differ",
   312	        ));
   313	    }
   314	    if input.policy.repository != input.startup.base.repository
   315	        || input.policy.admitted_uid != fs::metadata(output.parent().unwrap())?.uid()
   316	    {
   317	        return Err(error(
   318	            "policy repository/admitted UID differ from preparation selections",
   319	        ));
   320	    }
   321	    fs::create_dir(output)?;
   322	    fs::set_permissions(output, fs::Permissions::from_mode(0o700))?;
   323	    write(&output.join("input.json"), &bytes, 0o400)?;
   324	    write(&output.join("provenance.json"), &provenance_raw, 0o400)?;
   325	    subject(&mut input, output)?;
   326	    let d = &mut input.startup.base;
   327	    let q = &mut input.startup.qualified;
   328	    let verified = verify_existing_subject_dynamic(
   329	        &d.repository,
   330	        &d.identity,
   331	        &d.baseline,
   332	        &d.candidate.read(1024 * 1024)?,
   333	        &d.physical_profile.read(4 * 1024 * 1024)?,
   334	        &d.gate_capture.read(1024 * 1024)?,
   335	        &d.gate_manifest.read(1024 * 1024)?,
   336	        &d.gate_receipt.read(1024 * 1024)?,
   337	    )?;
   338	    let profile = TrustedClaudeProfile::load_installed(
   339	        pinned_program(&d.peer.executable)?,
   340	        pinned_program(&q.guard)?,
   341	        &q.requested_model,
   342	        &q.requested_effort,
   343	        q.accepted_observed_models.clone(),
   344	        &q.catalog.read(64 * 1024)?,
   345	    )
   346	    .map_err(|e| error(e.to_string()))?;
   347	    let rp0 = TrustedRp0Profile::load(
   348	        pinned_program(&q.bwrap)?,
   349	        pinned_program(&q.cbm)?,
   350	        pinned_program(&q.cbm_launcher)?,
   351	        pinned_program(&q.cbm_client)?,
   352	    )
   353	    .map_err(|e| error(e.to_string()))?;
   354	    let boundary = CandidateBoundary::prepare_selected(
   355	        rp0,
   356	        &d.repository,
   357	        output.join("native-boundary"),
   358	        &input.project,
   359	        &verified.reference.tree,
   360	    )
   361	    .map_err(|e| error(e.to_string()))?;
   362	    let (boundary, boundary_hash) = boundary
   363	        .publish_manifest()
   364	        .map_err(|e| error(e.to_string()))?;
   365	    q.boundary_root = output.join("native-boundary");
   366	    q.boundary_manifest_sha256 = boundary_hash;
   367	    let request = JobReviewRequest {
   368	        identity: d.identity.clone(),
   369	        candidate: verified.reference,
   370	        physical_profile_digest: verified.profile_digest,
   371	        cbm_store_sha256: boundary.index().store_sha256().into(),
   372	        session_id: d.peer.session.clone(),
   373	    };
   374	    let job = input.policy.jobs_root.join(request.directory_name()?);
   375	    if !input.policy.jobs_root.is_absolute()
   376	        || fs::canonicalize(&input.policy.jobs_root)? != input.policy.jobs_root
   377	        || fs::metadata(&input.policy.jobs_root)?.mode() & 0o077 != 0
   378	        || fs::metadata(&input.policy.jobs_root)?.uid() != input.policy.admitted_uid
   379	        || job.exists()
   380	    {
   381	        return Err(error(
   382	            "jobsRoot must be existing uid-private canonical directory and exact job must be absent",
   383	        ));
   384	    }
   385	    fs::create_dir(&job)?;
   386	    fs::set_permissions(&job, fs::Permissions::from_mode(0o700))?;
   387	    d.workspace = job.join("workspace");
   388	    run(
   389	        Path::new("/usr/bin/git"),
   390	        &[
   391	            "clone".into(),
   392	            "-q".into(),
   393	            "--no-hardlinks".into(),
   394	            d.repository.display().to_string(),
   395	            d.workspace.display().to_string(),
   396	        ],
   397	        output,
   398	    )?;
   399	    d.roots = crate::startup::Roots {
   400	        campaign: job.join("campaign"),
   401	        episode: job.join("episode"),
   402	        claims: job.join("claims"),
   403	        evidence: job.join("evidence"),
   404	    };
   405	    d.claims.source = copy_pin(output, "claims-source.json", &d.claims.source)?;
   406	    d.claims.configuration =
   407	        copy_pin(output, "claims-configuration.json", &d.claims.configuration)?;
   408	    // This is the proposed installed form, never an issued authority record.
   409	    // Preserve explicit source/writer selections and derive only exact subject identity.
   410	    let mut episode: Value = serde_json::from_slice(&d.episode_authority.read(1024 * 1024)?)?;
   411	    let episode_id = slice_campaign::contract::episode_digest(
   412	        &json!({"identity":d.identity,"obligationId":d.obligation_id}),
   413	    )?;
   414	    episode["identity"] = json!({"runId":d.identity.run_id,"sliceNumber":d.identity.slice_number,
   415	        "attemptId":d.identity.attempt_id,"planVersion":d.identity.plan_version,
   416	        "reviewObligationId":d.obligation_id,"reviewEpisodeId":&episode_id[..32]});
   417	    let subject_value = json!({"commit":request.candidate.commit,"tree":request.candidate.tree,"patchIdentity":request.candidate.patch_identity});
   418	    episode["initialSubject"]["revision"] = json!(request.candidate.commit);
   419	    episode["initialSubject"]["sha256"] = json!(review_episode_core::codec::digest(
   420	        &review_episode_core::codec::parse_json(&subject_value.to_string())?
   421	    ));
   422	    review_episode_core::identity::Authority::parse(review_episode_core::codec::parse_json(
   423	        &episode.to_string(),
   424	    )?)?;
   425	    d.episode_authority = data(&output.join("episode-authority.json"), &episode)?;
   426	    input.policy.startup_authority = JobStartupAuthority {
   427	        claims_source_sha256: d.claims.source.sha256.clone(),
   428	        claims_configuration_sha256: d.claims.configuration.sha256.clone(),
   429	        completion_consumer: q.completion_consumer.clone(),
   430	    };
   431	    let a = &mut input.policy.execution_template;
   432	    a["reference"] = json!(output.join("acceptance.proposed.json"));
   433	    a["revision"] = json!("unissued-preparation-proposal-v1");
   434	    for (key, value) in [
   435	        ("identity", json!(d.identity)),
   436	        ("attemptId", json!(d.identity.attempt_id)),
   437	        ("sessionId", json!(d.peer.session)),
   438	        ("candidateTree", json!(request.candidate.tree)),
   439	        (
   440	            "physicalProfileDigest",
   441	            json!(request.physical_profile_digest),
   442	        ),
   443	        ("cbmStoreSha256", json!(request.cbm_store_sha256)),
   444	        ("claudeProfileDigest", json!(profile.profile_digest())),
   445	        ("programSha256", json!(d.peer.executable.sha256)),
   446	        ("guardSha256", json!(q.guard.sha256)),
   447	        ("catalogSha256", json!(q.catalog.sha256)),
   448	        ("requestedModel", json!(q.requested_model)),
   449	        ("resourcePolicy", json!(q.resource_policy)),
   450	        (
